  const dfs = (r, c, node) => {
    const ch = board[r][c];
    const child = node.children[ch];
    if (!child) return;
    if (child.word !== null) {
      res.push(child.word);
      child.word = null;
    }
    board[r][c] = "#";
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] !== "#") {
        dfs(nr, nc, child);
      }
    }
    board[r][c] = ch;
  };

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      dfs(r, c, root);
